import{_ as e,c as p,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"噬嗑","description":"高島易斷 - 噬嗑","frontmatter":{"title":"噬嗑","description":"高島易斷 - 噬嗑"},"headers":[],"relativePath":"classics/takashima/021.md","filePath":"classics/takashima/021.md"}'),i={name:"classics/takashima/021.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="噬嗑" tabindex="-1">噬嗑 <a class="header-anchor" href="#噬嗑" aria-label="Permalink to “噬嗑”">​</a></h1><h2 id="噬嗑-1" tabindex="-1">噬嗑 <a class="header-anchor" href="#噬嗑-1" aria-label="Permalink to “噬嗑”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>噬嗑：亨，利用獄。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《雜卦》曰：“噬嗑，食也。”凡食下嚥則口合，有物梗之則口不合，不合則不通，合則亨通矣，故曰“噬嗑，亨”。由是而推之，在家庭則有讒邪以梗之，在朝廷則奸佞以梗之，在道路則有強暴以梗之。一如物之在口，有梗則不通也，欲期其通，當先治其梗，治梗者，“利用獄”。治獄宜剛，象取初上兩剛，用之者，則在五爻也。“獄”，囚也，外卦《離》體，外實中虛，有獄象焉。內卦《震》，《震》威也，外卦《離》，《離》明也，威而且明，有治獄之才焉，故曰“利”。如是而噬嗑濟矣。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>雷電《噬嗑》，先王以明罰敕法。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>《埤雅》曰：電與雷同氣，雷從回，電從申，陰陽以回薄而成雷，以申洩而為電，是皆天地之怒氣，震發而示威於天下者也，有用刑之象焉。或曰，雷出天氣，電出地氣，天地氣合而雷電作，《噬嗑》即以初上二剛為雷電。先王取其象以治獄，明以象電之光，敕以象雷之震，罰明使民知避，法敕使民知畏，斯罰無枉曲，法無偏私。朝廷之刑罰，一如天延之雷電。天以好生為德，王以恤刑為心，其道一也，其治隆矣。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：目下正當好運發動，有威儀，有光耀，聲名遠播上達之象，吉。</p><p>○　問商業：買者賣者，一時會集，有貨物旺銷之象，吉。</p><p>○　問家宅：天盤地盤皆動，防有火災，須小心謹慎，可以免禍。</p><p>○　問疾病：是鬱熱之症，導直透發，或熱極作狂，須慎。</p><p>○　問訟事：判決明允。</p><p>○　問天時：有雷雨驟降之象，雨後即霽。</p><p>○　問婚嫁：陰陽一氣，定必百年好合，吉。</p><p>○　問行人：即歸。</p><p>○　問失物：恐被人吞沒。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>《震》為足，初剛居陽在下，象足；初為《震》之下畫，亦象屨。“校”刑具，木校也，加校於屨，即加於足也。“滅”沒也，以校之小，僅沒其趾，罪小而罰輕也。初陽猶微，用刑亦寬，小懲之，使不復為惡而己，故用刑與受刑，兩“無咎”也。《象》曰“不行也”，古人制刑，有小罪則校其趾，禁止其行，使不敢復蹈前非，故曰“不行也”。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：目下防有小災，幸無大患，宜慎。</p><p>○　問商業：木材交易，最為不利，餘商亦宜謹慎。</p><p>○　問家宅：有興工改造之意，無咎。</p><p>○　問疾病：或足患瘡瘍，或患腳氣，症是初發，醫治自易。</p><p>○　問戰徵：防有埋伏，宜慎。</p><p>○　問婚嫁：不利。</p><p>○　問行人：未歸。</p><p>○　問六甲：生男。恐小兒有腳疾。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>明治二十三年春，友人某來謂曰：今欲合興一業，請佔成否？筮得《噬嗑》之《晉》。</p><p>斷曰：此卦下卦《震》為木，有動性，上卦《離》為火，其象恰如負薪向火，進必陷難，以勿進為宜。今佔初爻，曰“屨校滅趾，無咎”，然雖曰“無咎”，不免小懲。《象傳》曰“不行也”，明告以事不可行，宜罷而不復為。友人聞之曰：今得此佔，愈知其不可為也。餘所欲為，本非十全之策，當謝絕同人也。爾後友人又來曰：實三人同謀貸金業，若有以株券及公債證書為抵當借金者，返還之際，一依財主之便宜，予以證書，得借主承諾之證書貨金，其所抵當公債證書株券等，連即賣卻；又以同一方法貸與其金，次第如此，是不須資本，可得大利。若有請返還者，付以低落之株券等，萬一事不如意，則隱匿財產，為破產之策。後奸策發露，二人已下獄。《易》理之妙，實可驚歎！</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“膚”者，柔軟無骨之肉，噬之甚易，喻獄之易治；“滅鼻”者，喻得情之深。二爻應五，居中得正，是用刑之得其中正也。刑得中正，則罪人易服，雖“噬膚”而“滅鼻”，“無咎”也。互卦艮為鼻，此爻居艮之初，上有互卦之《坎》，以《艮》陷《坎》下，有滅鼻之象。《象傳》曰“乘剛也”，乘初之剛，以濟其柔，故噬之，而深沒其鼻也。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問時運：目下平平，因才力淺膚，宜乘大力者行事。</p><p>○　問商業：現時貨物，有輻輳而合之象，不妨深藏待價，乘時出售。吉。</p><p>○　問戰徵：“膚”大也，“鼻”始也，從今伊始，可奏膚功，吉。</p><p>○　問家宅：“鼻”為祖，“滅鼻”即滅祖，老宅不利。</p><p>○　問疾病：現下邪在肌膚，致恐深入為患。</p><p>○　問行人：偕伴而歸。</p><p>○　問婚嫁：定是興旺之家，可成。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治二十五年十月二十五日，杉浦重剛、菊地熊太郎、三宅雄次郎、志賀重昂、陸實諸學士，會於星罔茶寮，前一夕政府有命，停止《日本新聞》發行，時陸氏為該新聞主筆，問餘以解停之期，筮得《噬嗑》之《睽》。</p><p>斷曰：此卦“頤中有物”之象，噬之粉齏，自得亨也，故曰“噬嗑，亨”。今該新聞紙所載事項，有障害政府，政府停止發行，是其間為事所梗塞也。《噬嗑》之卦，“利用獄”，今六二居下，其罪不重。所謂“噬膚滅鼻”者，如噬美肉，誤為熱汁傷鼻，象編輯者匆促執筆，觸政府之忌諱，被折其鼻也。鼻屬金，滅鼻者，為停業而損貨財也。下卦為《震》，於數為八，此爻變為《兌》，《兌》數為九，今後八日，或至九日，必可解停。後八日，果解停。陸氏贈書，報知杉浦氏，感其奇中也。</p><p>親友某來曰：有一商業，為有望之事，請佔其成否並吉凶。筮得《噬嗑》之《睽》。</p><p>斷曰：此卦口中有物所梗，擬之商業，則為積貯物品之象。佔得二爻，是輕易看過商事，反來意外損失。“噬膚”者，謂肉柔而易噬，“滅鼻”者，為逢著剛強，商家致遭折鼻。故宜仔細留心，慎密從事，可無過也，故曰“噬膚滅鼻，無咎”也。後果如此佔。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>“臘肉”者，肉中藏骨，難噬之物也。骨藏肉中，人所不察，此爻以陰居陽，外柔內剛，有臘肉之象。乾肉歷久，噬之有肉敗生毒，互卦（三、四、五）為《坎》，《坎》者毒之象。肉毒，如罪人強暴，治之而遇反噬，是可吝也。然用刑非為不當，故雖可吝，吝亦小焉，終無咎也。《象傳》曰“位不當也”，柔居陽位，不得其當，故罪人不服，而反遇毒也。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：目下氣運不正，於得意事中，每多失意，或待人而反受人怨，幸無大害。</p><p>○　問商業：明明可獲利之業，或反有小損，多以處置不得其當。</p><p>○　問戰徵：屯營不得其地，防有小敗，宜謹守。</p><p>○　問家宅：宅神不安，恐有小災，宜禱。</p><p>○　問疾病：藥不對病，幸小病無礙。</p><p>○　問行人：因事未歸。</p><p>○　問六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>友人某來，請佔刑事裁判，筮得《噬嗑》之《離》。</p><p>斷曰：此卦為口中有物，不噬則不通，猶彼我之事，中間被人阻隔，非用力除之，不得調和。今佔得六三，曰“噬臘肉，遇毒”，臘肉肉中帶骨，堅韌難噬，久則有毒，如犯人剛強難治，久將反噬，未免有“小吝”也。然秉公審斷，終得罪狀，故曰“無咎”。裁判此案，自當審慎。後果如此佔。</p><p>佔明治三十年秋豐歉，筮得《噬嗑》之《離》。</p><p>斷曰：此卦頤中有物之象，佔年成豐兇得此卦，尤見適應也。三爻辭曰“噬臘肉，遇毒”。臘肉者，醃幹之小獸肉，體具備，臘時既久，易致生毒，是食物之不潔者也。此卦有雷電交作之象，防七八月間大雨發，損害田穀，秋收不足，穀食缺乏，致人民混食雜糧，或遇毒而致病，謂之“噬臘肉，遇毒”。然今有外國米穀，輸入甚便，得以濟飢，故曰“小吝，無咎”。是年八月，果氣候不順，洪水遍發，致米穀缺乏，幸輸入外國米，藉以濟荒。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>“乾胏”，乾肉之有骨者也，其堅至矣。堅以象九四之剛；肉柔骨堅，以象九四之陽居陰位。四剛在中，其治獄，必合初上兩剛而並治。初剛一畫為《乾》，《乾》為金，故初有金象；上剛一畫屬離，《離》為矢，故上有矢象。四近比五，為治獄之大吏，初上皆從之，故曰“得金矢”。金剛矢直，剛與直，為治獄之要道，九四得之，有何獄之不可治也！故乾胏雖堅韌，不難噬，猶言罪人雖強悍，不患不服矣。在四以柔居剛，剛或過嚴，故利用艱；柔或過寬，故利用貞，艱且貞，則吉矣。六爻中獨四稱吉。《象傳》曰“未光也”，謂治獄則吉，而四居《離》之初，高明猶微，故曰“未光也”。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運：目下改舊從新，正當盛運，萬事皆吉。</p><p>○　問商業：譬如食肉得金，有利過於本之象，大吉。</p><p>○　問家宅：家業素豐，安不忘危，常不忘變是保家要道，吉。</p><p>○　問戰徵：能獲敵糧餉，獲敵弓矢，無堅不摧，所向皆利。但勝時，更宜謹慎為吉。</p><p>○　問婚嫁：以勤儉之家，吉。</p><p>○　問產生：此症非易治，須謹慎調養，吉。</p><p>○　問六甲：生男。</p><p>○　問行人：在外得利，尚未歸也。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>相識某，因商業上生一大紛議，請佔其結果如何。筮得《噬嗑》之《頤》。</p><p>斷曰：此卦有隔絕被我於中，謀攫大利者，首當用力除去其害。今佔得四爻，曰“噬乾胏”，乾胏堅韌難噬，知其人必剛暴難治。曰“得金矢”，金矢貴重之品，想所以爭訟者，即在此貴重之金矢也。就金矢取象，金剛象，矢直象，必得一剛直之人，方能判決。然處置甚難，非一時可了，故曰“利艱貞”。始終忍耐，雖多紛議，自然歸結，可勿勞心也。後果如此佔。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>“噬乾肉”者，喻肉之無骨易噬。“得黃金”者，黃為正，取正中也；金為剛物，取堅剛也。此爻備剛明之德，尊居五位，即斷獄之君也。乾肉為肉已幹，獄而至於人君親決，亦必獄之已成者，罪雖已定，而人君猶有罪疑惟輕之意，故曰“貞厲”。如是而用刑，復何有咎？《象傳》曰“得當也”，謂能以柔用剛，守正慮危，治獄之道，得其當也。</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：運正得時，所求所謀，無不如意，吉。</p><p>○　問商業：所販運貨物，皆是上品，乾淨完美，大得利益；不特一時，此業可保長久。吉。</p><p>○　問家宅：方位得當，大利。</p><p>○　問戰徵：主敵城柔弱易攻，吉。</p><p>○　問疾病：肉食宣忌，久亦可危，須謹慎調攝。</p><p>○　問行人：正獲利歸來。</p><p>○　問六甲：生男。</p><p>○　問失物：即得。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>佔明治二十二年之米作，筮得《噬嗑》之《無妄》。</p><p>斷曰：《雜卦傳》曰：“噬嗑食也”；《象傳》曰：“頤中有物曰噬嗑，噬嗑而亨”，此卦辭皆關食物者也。此卦雷在下，電在上，互卦四爻為七八月，防有洪水。今佔得五爻，為豐作之兆也。爻辭曰“噬乾肉”，乾肉可藏，新谷登場，納之倉廩，亦取藏也。曰“得黃金”，稻得黃熟時，稱日遍野黃金，米粒稱曰金粒、玉粒，蓋言豐也。年豐谷熟，販運者廣，米價未必低落，農民既得十分收穫，又得高價出賣，亦謂之得黃金也。果至七八月間多雨，二三縣雖有被水慘狀，全國概得十分豐登，米價頗貴，知《易》理之精妙，不可測度。頃日會某貴顯，談及此佔，貴顯感嘆不措。</p><p>明治二十七年十二月，我海陸軍在清國山東省威海衛，清國軍艦據要地防禦，我軍艦在港外，炮擊不得其宜。是月二十日，餘偶會土方宮內大臣於汽車中，大臣問餘以威海衛戰況，餘筮得《噬嗑》之《無妄》。</p><p>斷曰：此卦為“頤中有物”之象，今清兵因過日之敗，退守僻地，我海陸兵包圍清國海軍，猶頤中有物也。今佔得五爻，戰機正熟，擊敵之堅，可有意外之獲也，謂之“噬乾肉，得黃金”。雖所行危險，可保無害，謂之“貞厲，無咎”也。後果伊東海軍中將，以水雷艇擊破鐵索，侵入港內，擊沉定遠等數軍艦，敵將丁汝昌以下自殺，鎮遠等軍艦，悉歸我有。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上居極位，在五之上，為《離》上畫，剛明過盛。“校”，木校，刑具也。初陽在下，故校在足；上陽在上，故校在首。“何校滅耳”，校之厚，知刑之酷也。治獄之道，與其失人，不如失出，宜以欽恤為心。上九剛強自用，重刑示威，安能無兇乎？故曰“兇”。《象傳》曰“聰不明也”，謂訟之聽，全在於聰，剛而不中，失其聰，即失其明，故曰“聰不明也”。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：目下大運已終，能以柔和處世，可保無慮，若任用強，難免兇矣。</p><p>○　問商業：得利即止，不可過貪，斯無大損。</p><p>○　問家宅：防有意外之災兇。</p><p>○　問戰徵：切勿前進，前進必兇。</p><p>○　問疾病：或耳鳴耳聾，或項上生毒，兇。</p><p>○　問六甲：生男，防有聾耳之疾。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>東京曲街酒店主人某，家業上夙操苦心，頃日忽然不理事務。一日午前出家，日暮未歸，家人尋之，不得蹤跡。時平川町盲人鈴木孝伯，嘗就餘學《易》，家人因請占卜，孝伯筮得《噬嗑》之《震》。</p><p>孝伯斷曰：此卦內為《震》雷，外為《離》火，南離方也，趨街之南。雷火發動者，蒸氣車也。佔得上爻，其辭曰“何校滅耳，兇”，以此推之，恐主人觸蒸氣車，有滅耳而死之象也。聞者皆驚，或猶未信，既而夜十時，愛宕下警察署急召喚家人，告以主人鐵道上橫死之事，驗之果首耳俱裂。至是皆敬服《易》理之妙。餘聞之，喜孝伯判斷酷似餘言，故附記之。</p><p>明治三十二年四月，某貴紳妻，初有孕，至臨月，逾期未產。為佔其分娩，用《易》筮，得《噬嗑》之《震》。</p><p>斷曰：《噬嗑》之卦，二陽在上下，一陽在三陰之間，即妊娠之象。今佔分娩，見有滅耳之辭，是胎兒肥大，難於生產，恐相軋而傷其耳也。後果此婦臨褥，久不得產，醫師見產婦不堪，將施行截開，漸而分娩。蓋因兒肥大，為產門所阻，致耳受傷，因以硝酸銀灼之，療其傷也。兒雖不至“滅耳”，其受傷也確矣。</p>',108)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
